            Describe.Lean(DescribeId.Create("positive-recoding-insplitnumberedrecoding-new-edge-equiv"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.newEdgeEquiv"), H("newEdgeEquiv"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Decode the ranked SR edges as actual incoming-split edges. The retained class and original edge determine the complete split edge."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-insplitnumberedrecoding-old-relabel"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.oldRelabel"), H("oldRelabel"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Package the original vertex numbering and old-edge decoding as a graph relabel. The endpoint laws connect actual histories to the counted RS graph."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-insplitnumberedrecoding-new-relabel"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.newRelabel"), H("newRelabel"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Package the incoming-split vertex numbering and new-edge decoding as a graph relabel from the counted SR graph."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-insplitnumberedrecoding-numbered-forget"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.numbered_forget"), H("numbered_forget"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Incoming FORGET is the opposite positive recoding, with no time shift."))), DescribeRole.Theorem),
            Describe.Remark(DescribeId.Create("positive-recoding-insplitnumberedrecoding-old-number"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.oldNumber"), H("oldNumber"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Choose the existing finite numbering of the original vertices. It supplies the old endpoint coordinates for both rectangular factors.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-insplitnumberedrecoding-new-number"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.newNumber"), H("newNumber"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Number the retained incoming-split vertices, including their class labels. This gives the new endpoint coordinates without collapsing classes.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-insplitnumberedrecoding-r"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.R"), H("R"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("R half-edges are original edges, ending at their incoming label class.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-insplitnumberedrecoding-s"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.S"), H("S"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("S half-edges are retained classes, returning to their old vertex.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-insplitnumberedrecoding-r-decode"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.rDecode"), H("rDecode"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Decode an R half-edge into its original edge and retained incoming class using the rectangular fiber enumerator.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-insplitnumberedrecoding-s-decode"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.sDecode"), H("sDecode"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Decode an S half-edge into its retained class and underlying old vertex. This is the complementary half of the incoming factorization.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-insplitnumberedrecoding-old-endpoints"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.old_endpoints"), H("old_endpoints"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Old-edge decoding preserves both numbered endpoints. These equations supply the old graph-relabel endpoint proofs.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-insplitnumberedrecoding-new-endpoints"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.new_endpoints"), H("new_endpoints"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("New-edge decoding preserves both incoming-split endpoints. These equations supply the new graph-relabel endpoint proofs.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-insplitnumberedrecoding-counted"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.counted"), H("counted"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("View the numbered edges of a square count matrix as a directed multigraph. This is the graph adapter used by the path-numbering maps.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-insplitnumberedrecoding-old-paths"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.oldPaths"), H("oldPaths"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Apply the inverse old relabel coordinatewise to number every original history as a path in RS. Discrete edge topology supplies the homeomorphism.")))),
