            Describe.Remark(DescribeId.Create("positive-recoding-insplitnumberedrecoding-numbered-lift"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/InSplitNumberedRecoding.numbered_lift"), H("numbered_lift"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Incoming LIFT is positive R,S with the necessary -1 correction.")))))));
